'use strict';

/**
* Create a zero-dimensional ndarray.
*
* @module @stdlib/ndarray-tensor0d-ctor
*
* @example
* var getDType = require( '@stdlib/ndarray-dtype' );
* var tensor0d = require( '@stdlib/ndarray-tensor0d-ctor' );
*
* var v = tensor0d();
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray-dtype' );
* var tensor0d = require( '@stdlib/ndarray-tensor0d-ctor' );
*
* var v = tensor0d( 1.0 );
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float64'
*
* @example
* var getDType = require( '@stdlib/ndarray-dtype' );
* var tensor0d = require( '@stdlib/ndarray-tensor0d-ctor' );
*
* var v = tensor0d( 1.0, 'float32' );
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float32'
*
* @example
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var getDType = require( '@stdlib/ndarray-dtype' );
* var tensor0d = require( '@stdlib/ndarray-tensor0d-ctor' );
*
* var buf = new ArrayBuffer( 8 );
* var v = tensor0d( buf );
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float64'
*
* @example
* var ArrayBuffer = require( '@stdlib/array-buffer' );
* var getDType = require( '@stdlib/ndarray-dtype' );
* var tensor0d = require( '@stdlib/ndarray-tensor0d-ctor' );
*
* var buf = new ArrayBuffer( 24 );
* var v = tensor0d( buf, 16 );
* // returns <ndarray>
*
* var dt = String( getDType( v ) );
* // returns 'float64'
*/

// MODULES //

var setReadOnly = require( '@stdlib/utils-define-nonenumerable-read-only-property' );
var factory = require( './factory.js' );
var main = require( './main.js' );


// MAIN //

setReadOnly( main, 'factory', factory );


// EXPORTS //

module.exports = main;

// exports: { "factory": "main.factory" }
